import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
config = json.loads((root / 'account-routing-defaults.json').read_text())
target = root / 'backend/internal/pkg/accountbalance/defaults_gen.go'
target.parent.mkdir(parents=True, exist_ok=True)


def string_array(go_name, config_key):
    entries = ''.join(f'\t{json.dumps(value, ensure_ascii=False)},\n' for value in config[config_key])
    return f'var {go_name} = [...]string{{\n{entries}}}\n'


target.write_text(
    '// Code generated by tools/generate_account_routing_defaults.py; DO NOT EDIT.\n'
    'package accountbalance\n\n'
    f'const QuotaGapPercent = {config["quota_gap_percent"]}\n'
    f'const QuotaSnapshotMaxAgeSeconds = {config["quota_snapshot_max_age_seconds"]}\n'
    f'const TakeoverHeaderWaitSeconds = {config["takeover_header_wait_seconds"]}\n'
    f'const TakeoverUpstreamIdleSeconds = {config["takeover_upstream_idle_seconds"]}\n'
    f'const TakeoverTotalWaitSeconds = {config["takeover_total_wait_seconds"]}\n\n'
    f'const OpenAIUpstreamUnavailableCooldownSeconds = {config["openai_upstream_unavailable_cooldown_seconds"]}\n'
    f'const OpenAIWSUnavailableFallbackCooldownSeconds = {config["openai_ws_unavailable_fallback_cooldown_seconds"]}\n\n'
    + string_array('OpenAIRelayIncompatible400Keywords', 'openai_relay_incompatible_400_keywords')
    + '\n'
    + string_array('OpenAIUpstreamUnavailableHTTPKeywords', 'openai_upstream_unavailable_http_keywords')
)
